query getFlashApps {
    myself {
        flashApps {
            id
            name
            flashEnvironments {
                id
                name
                state
                createdAt
                activeBuildId
            }
            flashBuilds { id createdAt }
        }
    }
}

query getFlashApps {
    myself {
        flashApps {
            id
            name
            flashEnvironments {
                id
                name
                state
                createdAt
                activeBuildId
            }
            flashBuilds { id createdAt }
        }
    }
}

